  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
begin
  select jsonb_agg(jsonb_build_object(
    'lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision
  ) order by ordinality)
    into v_points
    from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);
  select h.id,h.latitude,h.longitude,h.published,h.trace_available,
      h.official_url,h.description,h.distance_km,
      t.status,t.segments,t.geometry_source_url,t.official,t.continuity_checked
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-4161075'
      and h.source='openstreetmap'
      and h.name='Ermita de Castro-Torreciudad'
      and h.route_ref='PR-HU 75'
      and h.raw_tags->>'ref'='PR-HU 75'
      and h.source_url='https://www.openstreetmap.org/relation/4161075'
      and h.official_url in (
        'http://senderos.turismoribagorza.org/ficha.php?id_ruta=103',
        'https://turismoribagorza.org/ruta/pr-hu-75-ermita-de-castro-torreciudad/')
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.region_code='huesca' and r.published)
    for update of h,t;
  if not found then
    raise exception 'PR-HU 75 route identity or published region changed';
  end if;
  if v_route.status='ready' then
    if v_route.geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/31_pr-hu_75.gpx'
      and v_route.segments=jsonb_build_array(v_points)
      and v_route.official and v_route.continuity_checked
      and v_route.published and v_route.trace_available
      and v_route.official_url='https://turismoribagorza.org/ruta/pr-hu-75-ermita-de-castro-torreciudad/'
      and v_route.distance_km=9.65 then
      return;
    end if;
    raise exception 'PR-HU 75 route has another ready trace or publication state';
  end if;
  if v_route.status<>'missing' or v_route.published or v_route.trace_available
    or v_route.segments is not null or v_route.geometry_source_url is not null
    or v_route.description is not null or v_route.distance_km is not null then
    raise exception 'PR-HU 75 hidden route state changed';
  end if;
  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
      (lat between 42.10 and 42.20 and lon between 0.23 and 0.34) valid
    from steps
  )
  select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
    coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;
  select ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint(0.300946,42.125126)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision),
    ST_MakePoint(0.237489,42.169027))
    into v_start_gap_m,v_end_gap_m;
  if v_count<>597 or v_invalid>0
    or abs(v_length_km-9.654026)>0.015
    or v_max_gap_km>0.152 or v_center_gap_km>0.85
    or v_start_gap_m>2 or v_end_gap_m>2 then
    raise exception 'PR-HU 75 GPS validation failed: points %, length %, gap %, center %, start %, end %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,
      v_start_gap_m,v_end_gap_m,v_invalid;
  end if;
  update public.hiking_route_tracks
    set status='ready',segments=jsonb_build_array(v_points),checked_at=now(),
      continuity_checked=true,
      geometry_source='Comarca de Ribagorza - GPX oficial PR-HU 75',
      geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/31_pr-hu_75.gpx',official=true
    where route_id=v_route.id and status='missing';
  if not found then
    raise exception 'PR-HU 75 track state changed';
  end if;
  update public.hiking_routes
    set trace_available=true,published=true,
      distance_km=round(v_length_km::numeric,2),route_type='Lineal',
      official_url='https://turismoribagorza.org/ruta/pr-hu-75-ermita-de-castro-torreciudad/',
      description='PR-HU 75 de la ermita de Castro a Torreciudad por La Puebla de Castro, Ubiergo y Bolturina. El GPX oficial contiene la ida: 9,65 km. El regreso se realiza por el mismo camino. Los 19,705 km, 6 h 10 min y 645 m de subida de la ficha oficial corresponden a la ida y vuelta. Este itinerario es el enlace con Torreciudad; el sendero circular PR-HU 75 de La Puebla de Castro es otro recorrido.'
    where id=v_route.id and not published and not trace_available;
  if not found then
    raise exception 'PR-HU 75 publication state changed';
  end if;
end
$curate$;
